import re

def parsea_duracion(s):
    if not isinstance(s, str) or not s:
        raise ValueError("Cadena vacía o no válida")

    # Patrón para capturar horas, minutos y segundos en cualquier orden
    pattern = r'^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$'
    match = re.match(pattern, s)

    if not match:
        raise ValueError(f"Cadena de duración no válida: {s}")

    h_str, m_str, s_str = match.groups()

    # Asegurarse de que al menos un componente esté presente
    if h_str is None and m_str is None and s_str is None:
        raise ValueError(f"Cadena de duración no válida: {s}")

    total_seconds = 0
    if h_str:
        total_seconds += int(h_str) * 3600
    if m_str:
        total_seconds += int(m_str) * 60
    if s_str:
        total_seconds += int(s_str)

    return total_seconds
```

